#include <bits/stdc++.h>
using namespace std;int main(){int h,w;cin>>h>>w;vector<string>g(h);for(auto&x:g)cin>>x;vector<vector<int>>d(h,vector<int>(w,-1));queue<pair<int,int>>q;for(int i=0;i<h;i++)for(int j=0;j<w;j++)if(g[i][j]=='S')d[i][j]=0,q.push({i,j});int z[4][2]={{1,0},{-1,0},{0,1},{0,-1}};while(!q.empty()){auto [i,j]=q.front();q.pop();for(auto&e:z){int x=i+e[0],y=j+e[1];if(x>=0&&x<h&&y>=0&&y<w&&g[x][y]!='#'&&d[x][y]<0)d[x][y]=d[i][j]+1,q.push({x,y});}}bool f=1;for(int i=0;i<h;i++)for(int j=0;j<w;j++)if(g[i][j]=='T'){if(!f)cout<<' ';f=0;cout<<d[i][j];}if(f)cout<<0;cout<<'\n';}